    var gitOpsMock = Object.assign({
        writePRContext: function() {},
        checkoutPRBranch: function() {},
        getPRDiff: function() { return ''; }
    }, mocks && mocks.gitOpsMock || {});

    return loadModule(
        'js/prepareTestPRForReview.js',
        makeRequire({
            './config.js': configModule,
