    });

    test('throws when params.ticket has no key', function() {
        var wipLabel = loadCheckWipLabel({});
        assert.throws(function() {
            wipLabel.action({ ticket: { fields: {} }, metadata: { contextId: 'story_development' }, jobParams: {} });
